INSERT INTO episodes (id, title, description, created_at) VALUES 
('0efd56dc-9c2b-424a-be8b-c50edb283914', 'The Algorithmic Class Divide', 'How redlining turned into algorithmic bias. Exploring the historical roots of discriminatory lending practices and their modern AI-powered manifestations in credit scoring and mortgage approval systems.', 1762017406475),
('1b2e1e74-8cd4-4da1-8a45-0001e9ba7cab', 'Investing in Liberation: AI as a Tool for Economic Justice', 'Can machine learning models be used to identify and fund underserved communities? A conversation about using AI to democratize access to capital.', 1762017406850),
('7d4d4ce7-6bce-431b-9059-5d4c786127bf', 'The Ghost in the Machine: Bias Audits for Financial AI', 'Deep dive into fairness testing frameworks, intersectional bias detection, and the regulatory landscape for AI in finance.', 1762017407250),
('8cdcc389-808a-4408-b3fa-d26c452f1cdb', 'Decolonizing Data: Who Owns the Training Sets?', 'Examining data extraction, consent, and ownership in AI systems used for credit and risk assessment in the Global South.', 1762017407553),
('d55804dd-ad35-4022-b69f-3dba16202e6e', 'From Payday Loans to Prediction Markets: AI and Financial Predation', 'How AI-powered fintech can either exploit or empower vulnerable populations. Case studies from predatory lending detection systems.', 1762017407867),
('f6682aab-64b8-4766-84c8-6c5122384ef6', 'The Builder and The Critic: This format moves beyond a simple debate to create a constructive dialogue between a leading AI founder and a premier critic of AI''s social impact', 'This format moves beyond a simple debate to create a constructive dialogue between a leading AI founder and a premier critic of AI''s social impact. The objective is to explore how deep critique can inform the foundational design philosophy of new technologies, moving ethics from a compliance checklist to a core product principle. Kanjun Qiu is building AI with the explicit goal of enhancing human agency and creativity. Ruha Benjamin''s work meticulously documents how current technological systems often disempower and harm marginalized communities, and she offers "abolitionist tools" for a more just approach. The guiding question for this conversation is not "Is AI good or bad?" but rather: How could Benjamin''s "abolitionist tools" be practically integrated into the architectural and ethical framework of an AI company like Imbue from its inception? This dialogue would transform a powerful critique into a potential design specification, offering a roadmap for a more equitable mode of AI development. Featuring Kanjun Qiu (CEO, Imbue) & + Ruha Benjamin (Author, Race After Technology).', 1762017835528),
('6d8ee9ca-7b33-4ed1-b059-ea5ad6d7a6c0', 'The Code and The Consequence: This pairing juxtaposes a technologist creating sophisticated, automated governance systems with a researcher who has documented the devastating real-world failures of similar systems', 'This pairing juxtaposes a technologist creating sophisticated, automated governance systems with a researcher who has documented the devastating real-world failures of similar systems. This grounds the promise of technical solutions in the lived experience of those most affected by their implementation. John Nay is building "Regulatory AI" to automate legal and regulatory compliance, aiming to create more efficient and auditable systems of governance. Virginia Eubanks'' research provides a harrowing account of how automated welfare and social service systems have created a "digital poorhouse," punishing the poor for minor errors and reinforcing systemic bias. The core tension to explore is: Can Nay''s sophisticated, law-as-code approach be a genuine solution to the bureaucratic injustices Eubanks identifies, or does it risk creating an even more efficient and inescapable "digital poorhouse"? This conversation would force a pragmatic visionary to confront the human consequences of automated decision-making at its most brutal. Featuring John Nay (Founder, Norm AI) & + Virginia Eubanks (Author, Automating Inequality).', 1762017836207),
('87a00f4e-f062-4658-9626-5c0325a24d29', 'The Capital and The Culture: This discussion brings together two leaders who deploy capital to shape culture and drive social change, but who operate at vastly different scales and with divergent risk profiles', 'This discussion brings together two leaders who deploy capital to shape culture and drive social change, but who operate at vastly different scales and with divergent risk profiles. The conversation would be a meta-analysis of the podcast''s own title, exploring the different strategies of ''Renegade Capital''. Darren Walker helms a multi-billion-dollar institution, working to steer its immense resources toward justice and equity from within the establishment. Christine Kuan leads a nimble organization founded specifically to fund the risk-taking, avant-garde artists that larger institutions might overlook. The guiding question is: What are the distinct and complementary roles of large-scale institutional philanthropy and agile, "renegade" funding in fostering a just and creatively vibrant society? Where do they overlap, and where must they necessarily diverge? This would be a masterclass in the strategy of social change through financial leverage. Featuring Darren Walker (President, Ford Foundation) & + Christine Kuan (President, Creative Capital).', 1762017836900),
('77bd3f2e-0f54-4bf8-9e6a-79531b18c649', 'The Future of Human Labor (Part 1): The Economist''s View', 'A three-episode series that examines the impact of AI on the future of work from three distinct and crucial perspectives: the macro-economist, the on-the-ground labor organizer, and the life-course strategist. The arc would begin with Daron Acemoglu, who can lay out the stark economic framework of automation''s "displacement effect" on labor and the societal danger of the "Turing Trap". Featuring Daron Acemoglu.', 1762017837553),
('2ed59538-7c76-4448-83ea-4827db13b65f', 'The Future of Human Labor (Part 2): The Worker''s View', 'A three-episode series that examines the impact of AI on the future of work from three distinct and crucial perspectives: the macro-economist, the on-the-ground labor organizer, and the life-course strategist. Featuring , Ai-jen Poo.', 1762017838182),
('6fbcb738-8861-43d3-8baa-44c9f8e57925', 'The Future of Human Labor (Part 3): The Life-Course View', 'A three-episode series that examines the impact of AI on the future of work from three distinct and crucial perspectives: the macro-economist, the on-the-ground labor organizer, and the life-course strategist. Featuring , and Lynda Gratton.', 1762017838483);
